 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(w)] for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3:
                continue
            # A five-cell cap and a three-row, two-sided frame around each marker.
            for x in range(c - 2, c + 3):
                out[r - 2][x] = 5
            for y in range(r - 1, r + 2):
                out[y][c - 2] = 2
                out[y][c + 2] = 2
            out[r - 1][c] = 5
            out[r][c] = 3
            # The lower scanline is color 2, with the frame's opening in color 8.
            for x in range(w):
                out[r + 2][x] = 2
            for x in range(c - 2, c + 3):
                out[r + 2][x] = 8
    return out
